def _on(name: str, x: torch.Tensor) -> bool:
    return KERNELS[name] and x.is_cuda


def _needs_grad(*xs: torch.Tensor) -> bool:
    return torch.is_grad_enabled() and any(x.requires_grad for x in xs)


def metal_enabled() -> bool:
